    private static Component objectGlyph(){try{Class<?> info=Class.forName("net.minecraft.network.chat.contents.objects.ObjectInfo"),sprite=Class.forName("net.minecraft.network.chat.contents.objects.PlayerSprite"),profile=Class.forName("net.minecraft.world.item.component.ResolvableProfile");Object player=profile.getMethod("createUnresolved",String.class).invoke(null,"Cy3807");Object object=sprite.getConstructor(profile,boolean.class).newInstance(player,true);return (Component)Component.class.getMethod("object",info).invoke(null,object);}catch(ClassNotFoundException expectedOn1218){return null;}catch(Exception failure){throw new AssertionError(failure);}}

    private static boolean hasNumber(Style style){if(style==null||style.getInsertion()==null)return false;try{String marker=style.getInsertion();String[] ids=marker.substring(marker.lastIndexOf(':',marker.lastIndexOf(':')-1)+1).split(":");Object message=((ChatHistory<?>)staticField(ChatAssist.class,"HISTORY")).get(Long.parseLong(ids[0]));Object part=((List<?>)field(message,"parts")).get(Integer.parseInt(ids[1]));return field(part,"number")!=null;}catch(Exception e){throw new AssertionError(e);}}
    private static boolean hasKind(Style style,Kind expected){if(style==null||style.getInsertion()==null)return expected==null;try{String marker=style.getInsertion();String[] ids=marker.substring(marker.lastIndexOf(':',marker.lastIndexOf(':')-1)+1).split(":");Object message=((ChatHistory<?>)staticField(ChatAssist.class,"HISTORY")).get(Long.parseLong(ids[0]));Object part=((List<?>)field(message,"parts")).get(Integer.parseInt(ids[1]));List<?> targets=(List<?>)field(part,"targets");return expected==null?targets.isEmpty():targets.stream().anyMatch(t->((Target)t).kind()==expected);}catch(Exception e){throw new AssertionError(e);}}
    private static String displayTitle(WorldEntityScreen screen){try{var m=WorldEntityScreen.class.getDeclaredMethod("displayTitle");m.setAccessible(true);return (String)m.invoke(screen);}catch(Exception e){throw new AssertionError(e);}}
    private static Object staticField(Class<?> type,String name){try{var f=type.getDeclaredField(name);f.setAccessible(true);return f.get(null);}catch(Exception e){throw new AssertionError(e);}}
    private static Object field(Object object,String name){try{var f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(Exception e){throw new AssertionError(e);}}
